import { GEO } from './cuenca-geodata.js';

// js/city-config.js
// Cuenca (Azuay, Ecuador) spatial configuration at true 1:1 scale, derived from js/cuenca-geodata.js (generated by
// tools/build-cuenca-geodata.mjs from OpenStreetMap).
//
// World frame: 1 unit = 1 m, x = grid east, z = grid south (north = -z), origin at Parque Calderón; the axes are turned
// GEO.frame.bearingDeg from true north, like the colonial street grid itself.

const toPts = (flat) => {
  const out = [];
  for (let i = 0; i < flat.length; i += 2) out.push({ x: flat[i], z: flat[i + 1] });
  return out;
};

// ---------------------------------------------------------------------------------------------------------------------
// Bounds
// ---------------------------------------------------------------------------------------------------------------------
const ISLAND_BOUNDS = { ...GEO.frame.bounds, sidewalkHeight: 0.22, waterLevel: -2.2 };
// Cuenca has no shoreline: the playable area is the extent of the road data
function getIslandBoundsAtZ() {
  return { westX: ISLAND_BOUNDS.minX, eastX: ISLAND_BOUNDS.maxX };
}
// Park-wide open-sky / raised-lawn zone of the NYC build; Cuenca's parks are ordinary blocks, so the zone is empty
const CENTRAL_PARK_BOUNDS = { minX: 1e7, maxX: 1e7 + 1, minZ: 1e7, maxZ: 1e7 + 1 };
const NJ_SHORELINE_POLYGON = [];
const LONG_ISLAND_POLYGONS = [];


// ---------------------------------------------------------------------------------------------------------------------
// Terrain: SRTM elevations on a 100 m grid (metres relative to Parque Calderón), interpolated over the very triangles the
// terrain mesh is drawn with (cell diagonal from the (i, j+1) corner to the (i+1, j) corner), so roads follow it exactly
// ---------------------------------------------------------------------------------------------------------------------
const TERRAIN = GEO.terrain || { x0: -1, z0: -1, step: 1, nx: 2, nz: 2, baseElevation: 0, h: [0, 0, 0, 0] };
const TERRAIN_BASE = TERRAIN.baseElevation;
function terrainHeightAt(x, z) {
  const { x0, z0, step, nx, nz, h } = TERRAIN;
  let fx = (x - x0) / step;
  let fz = (z - z0) / step;
  fx = Math.max(0, Math.min(nx - 1.0001, fx));
  fz = Math.max(0, Math.min(nz - 1.0001, fz));
  const i = Math.floor(fx), j = Math.floor(fz);
  const tx = fx - i, tz = fz - j;
  const h00 = h[j * nx + i], h10 = h[j * nx + i + 1], h01 = h[(j + 1) * nx + i], h11 = h[(j + 1) * nx + i + 1];
  return tx + tz <= 1 ? h00 + tx * (h10 - h00) + tz * (h01 - h00) : h11 + (1 - tx) * (h01 - h11) + (1 - tz) * (h10 - h11);
}

// ---------------------------------------------------------------------------------------------------------------------
// Named roads & nearest-road lookup (labels)
// ---------------------------------------------------------------------------------------------------------------------
const ROADS = GEO.roads.map(([name, w, dir, lanes, hw, flat]) => ({ name, w, dir, lanes, highway: !!hw, pts: toPts(flat) }));
const ROAD_CELL = 64;
const ROAD_GRID = new Map();
for (const r of ROADS) {
  for (let i = 0; i + 1 < r.pts.length; i++) {
    const a = r.pts[i];
    const b = r.pts[i + 1];
    const seg = { r, ax: a.x, az: a.z, bx: b.x, bz: b.z };
    const ix0 = Math.floor(Math.min(a.x, b.x) / ROAD_CELL), ix1 = Math.floor(Math.max(a.x, b.x) / ROAD_CELL);
    const iz0 = Math.floor(Math.min(a.z, b.z) / ROAD_CELL), iz1 = Math.floor(Math.max(a.z, b.z) / ROAD_CELL);
    for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
      const k = ix * 100000 + iz;
      if (!ROAD_GRID.has(k)) ROAD_GRID.set(k, []);
      ROAD_GRID.get(k).push(seg);
    }
  }
}
/** Nearest roads to (x, z) within `radius`: [{ road, dist, horizontal, x, z, dx, dz }] sorted by distance (one entry per road name) */
function nearestRoads(x, z, radius = 60, named = true) {
  const best = new Map();
  const ix0 = Math.floor((x - radius) / ROAD_CELL), ix1 = Math.floor((x + radius) / ROAD_CELL);
  const iz0 = Math.floor((z - radius) / ROAD_CELL), iz1 = Math.floor((z + radius) / ROAD_CELL);
  for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
    const list = ROAD_GRID.get(ix * 100000 + iz);
    if (!list) continue;
    for (const s of list) {
      if (named && !s.r.name) continue;
      const dx = s.bx - s.ax, dz = s.bz - s.az;
      const L2 = dx * dx + dz * dz || 1e-9;
      const t = Math.max(0, Math.min(1, ((x - s.ax) * dx + (z - s.az) * dz) / L2));
      const px = s.ax + t * dx, pz = s.az + t * dz;
      const d = Math.hypot(px - x, pz - z);
      if (d > radius) continue;
      const key = s.r.name || `#${ix},${iz}`;
      const prev = best.get(key);
      if (!prev || d < prev.dist) best.set(key, { road: s.r, dist: d, horizontal: Math.abs(dx) > Math.abs(dz), x: px, z: pz, dx, dz });
    }
  }
  return [...best.values()].sort((a, b) => a.dist - b.dist);
}
/** A drivable point on the closest street to (x, z), with the heading along it (0 faces south / +z, PI north) */
function roadSpotNear(x, z, radius = 200) {
  const drivable = nearestRoads(x, z, radius, false).filter((r) => r.road.w >= 6 && !r.road.highway);
  const hit = drivable[0] || nearestRoads(x, z, radius * 4, false)[0];
  if (!hit) return { x, z, heading: 0 };
  const L = Math.hypot(hit.dx, hit.dz) || 1;
  // Heading h faces (sin h, cos h): along the street, towards the side that looks at the target when there is one
  let hx = hit.dx / L, hz = hit.dz / L;
  if (hx * (x - hit.x) + hz * (z - hit.z) < 0) { hx = -hx; hz = -hz; }
  return { x: hit.x, z: hit.z, heading: Math.atan2(hx, hz) };
}

// ---------------------------------------------------------------------------------------------------------------------
// Blocks: land between the roadways, with the OSM buildings as lots
//   poly: block outline [{x, z}], park: 1 if parkland, parkName, frames: [[θ, px, pz, [[x0, x1, z0, z1]], height], ...]
// ---------------------------------------------------------------------------------------------------------------------
const BLOCKS = GEO.blocks.map(([flat, rects, park, parkName, isRect, frames], id) => {
  const poly = toPts(flat);
  let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity, a = 0, cx = 0, cz = 0;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const p = poly[i], q = poly[j];
    minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x); minZ = Math.min(minZ, p.z); maxZ = Math.max(maxZ, p.z);
    const c = q.x * p.z - p.x * q.z;
    a += c; cx += (q.x + p.x) * c; cz += (q.z + p.z) * c;
  }
  a *= 0.5;
  return {
    id, poly, rects, frames: frames || null, park, parkName, rect: !!isRect, area: Math.abs(a),
    minX, maxX, minZ, maxZ,
    cx: a ? cx / (6 * a) : (minX + maxX) / 2,
    cz: a ? cz / (6 * a) : (minZ + maxZ) / 2,
    median: false
  };
});

// Each block's sidewalk is a plane through the terrain under it, lifted to clear the terrain everywhere:
// y(x, z) = plane.c + plane.a * (x - plane.cx) + plane.b * (z - plane.cz)
for (const b of BLOCKS) {
  const pts = [];
  const nx = Math.max(2, Math.min(7, Math.ceil((b.maxX - b.minX) / 25)));
  const nz = Math.max(2, Math.min(7, Math.ceil((b.maxZ - b.minZ) / 25)));
  for (let i = 0; i <= nx; i++) {
    for (let j = 0; j <= nz; j++) {
      const x = b.minX + ((b.maxX - b.minX) * i) / nx, z = b.minZ + ((b.maxZ - b.minZ) * j) / nz;
      if (pointInPoly(b.poly, x, z)) pts.push([x, z, terrainHeightAt(x, z)]);
    }
  }
  for (const p of b.poly.length > 40 ? b.poly.filter((_, k) => k % Math.ceil(b.poly.length / 40) === 0) : b.poly) pts.push([p.x, p.z, terrainHeightAt(p.x, p.z)]);
  const cx = b.cx, cz = b.cz;
  // least squares for h = c + a dx + b dz
  let n = 0, sx = 0, sz = 0, sxx = 0, szz = 0, sxz = 0, sh = 0, sxh = 0, szh = 0;
  for (const [x, z, h] of pts) {
    const dx = x - cx, dz = z - cz;
    n++; sx += dx; sz += dz; sxx += dx * dx; szz += dz * dz; sxz += dx * dz; sh += h; sxh += dx * h; szh += dz * h;
  }
  let pa = 0, pb = 0, pc = n ? sh / n : 0;
  const det = n * (sxx * szz - sxz * sxz) - sx * (sx * szz - sxz * sz) + sz * (sx * sxz - sxx * sz);
  if (n >= 3 && Math.abs(det) > 1e-6) {
    // Cramer's rule on [n sx sz; sx sxx sxz; sz sxz szz] [c a b]' = [sh sxh szh]'
    const d = (m) => m[0] * (m[4] * m[8] - m[5] * m[7]) - m[1] * (m[3] * m[8] - m[5] * m[6]) + m[2] * (m[3] * m[7] - m[4] * m[6]);
    const M = [n, sx, sz, sx, sxx, sxz, sz, sxz, szz];
    const D = d(M);
    pc = d([sh, sx, sz, sxh, sxx, sxz, szh, sxz, szz]) / D;
    pa = d([n, sh, sz, sx, sxh, sxz, sz, szh, szz]) / D;
    pb = d([n, sx, sh, sx, sxx, sxh, sz, sxz, szh]) / D;
  }
  // lift to clear every sample, and keep the lowest terrain point for the slab's underside
  let lift = -Infinity, low = Infinity;
  for (const [x, z, h] of pts) {
    lift = Math.max(lift, h - (pc + pa * (x - cx) + pb * (z - cz)));
    low = Math.min(low, h);
  }
  b.plane = { a: pa, b: pb, c: pc + Math.max(0, lift), cx, cz, low: Number.isFinite(low) ? low : pc };
}
const planeAt = (b, x, z) => b.plane.c + b.plane.a * (x - b.plane.cx) + b.plane.b * (z - b.plane.cz);

const BLOCK_CELL = 64;
const BLOCK_GRID = new Map();
for (const b of BLOCKS) {
  for (let ix = Math.floor(b.minX / BLOCK_CELL); ix <= Math.floor(b.maxX / BLOCK_CELL); ix++) {
    for (let iz = Math.floor(b.minZ / BLOCK_CELL); iz <= Math.floor(b.maxZ / BLOCK_CELL); iz++) {
      const k = ix * 100000 + iz;
      if (!BLOCK_GRID.has(k)) BLOCK_GRID.set(k, []);
      BLOCK_GRID.get(k).push(b);
    }
  }
}
function pointInPoly(poly, x, z) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const a = poly[i], b = poly[j];
    if ((a.z > z) !== (b.z > z) && x < ((b.x - a.x) * (z - a.z)) / (b.z - a.z) + a.x) inside = !inside;
  }
  return inside;
}
/** The block (raised sidewalk island) under (x, z), or null on the roadway */
function blockAt(x, z) {
  const list = BLOCK_GRID.get(Math.floor(x / BLOCK_CELL) * 100000 + Math.floor(z / BLOCK_CELL));
  if (!list) return null;
  for (const b of list) {
    if (x < b.minX || x > b.maxX || z < b.minZ || z > b.maxZ) continue;
    if (pointInPoly(b.poly, x, z)) return b;
  }
  return null;
}

/**
 * Height of the walking / driving surface at (x, z): the sidewalk or lawn plane of the block there, else the road on
 * the terrain. 'person' walks on the sidewalk; vehicles ride the road.
 */
function groundHeightAt(x, z, mode = 'person') {
  const b = blockAt(x, z);
  if (b) return planeAt(b, x, z) + (b.park > 0.5 ? 0.06 : 0.22);
  return terrainHeightAt(x, z) + (mode === 'person' ? 0.03 : 0.03);
}

/** Blocks whose bounds overlap a rectangle */
function blocksInRect(minX, maxX, minZ, maxZ) {
  const out = new Set();
  for (let ix = Math.floor(minX / BLOCK_CELL); ix <= Math.floor(maxX / BLOCK_CELL); ix++) {
    for (let iz = Math.floor(minZ / BLOCK_CELL); iz <= Math.floor(maxZ / BLOCK_CELL); iz++) {
      const list = BLOCK_GRID.get(ix * 100000 + iz);
      if (list) for (const b of list) if (b.maxX > minX && b.minX < maxX && b.maxZ > minZ && b.minZ < maxZ) out.add(b);
    }
  }
  return [...out];
}

// ---------------------------------------------------------------------------------------------------------------------
// Landmarks (real footprints from OpenStreetMap) and teleports
// ---------------------------------------------------------------------------------------------------------------------
const LANDMARK_SITES = GEO.landmarks;
// [id, full name, short name, OSM name, barrio]
const LANDMARK_DEFS = [
  ['catedral', 'Catedral de la Inmaculada Concepción', 'Catedral Nueva', 'Catedral de la Inmaculada Concepción', 'Centro Histórico'],
  ['sagrario', 'El Sagrario (Catedral Vieja)', 'El Sagrario', 'El Sagrario Catedral Vieja', 'Centro Histórico'],
  ['sanfrancisco', 'Iglesia de San Francisco', 'San Francisco', 'Iglesia San Francisco', 'Centro Histórico'],
  ['conceptas', 'Monasterio de las Conceptas', 'Las Conceptas', 'Las Conceptas', 'Centro Histórico'],
  ['santodomingo', 'Basílica de Santo Domingo', 'Santo Domingo', 'Basílica Católica Santísimo Rosario - Santo Domingo ', 'Centro Histórico'],
  ['mercado10', 'Mercado 10 de Agosto', 'Mercado 10 Ago', 'Mercado 10 de Agosto', 'Centro Histórico'],
  ['todossantos', 'Todos Santos', 'Todos Santos', 'Todos Santos', 'El Barranco'],
  ['sanblas', 'Iglesia de San Blas', 'San Blas', 'Iglesia San Blas', 'San Blas'],
  ['bancocentral', 'Banco Central del Ecuador (Pumapungo)', 'Pumapungo', 'Banco Central del Ecuador', 'Pumapungo'],
  ['terminal', 'Terminal Terrestre', 'Terminal', 'Terminal Terrestre', 'Terminal'],
  ['universidad', 'Universidad de Cuenca', 'U. de Cuenca', 'Universidad de Cuenca', 'Universitario'],
  ['mallrio', 'Mall del Río', 'Mall del Río', 'Mall del Rio', 'Mall del Río'],
  ['turi', 'Iglesia de Turi', 'Turi', 'Iglesia Nuestra Señora de La Merced de Turi', 'Turi']
];
const CUENCA_LANDMARKS = LANDMARK_DEFS.filter(([, , , osm]) => LANDMARK_SITES[osm]).map(([id, name, short, osm, district]) => {
  const s = LANDMARK_SITES[osm];
  return { id, name, short, district, x: s.x, z: s.z, w: s.w, d: s.d, h: s.h };
});

// Street-level arrivals shared by every travel mode: the street next to each landmark
const spot = (id) => {
  const lm = CUENCA_LANDMARKS.find((l) => l.id === id);
  const s = roadSpotNear(lm.x, lm.z, 150);
  // Face the landmark from the road
  return { x: s.x, z: s.z, heading: Math.atan2(lm.x - s.x, lm.z - s.z) };
};
const TELEPORT_LOCATIONS = {};
{
  // On the street along the north side of the square, looking across it at the cathedral
  const cathedral = CUENCA_LANDMARKS.find((l) => l.id === 'catedral') || { x: 0, z: 26 };
  const calderon = roadSpotNear(cathedral.x + 60, cathedral.z - 95, 120);
  TELEPORT_LOCATIONS.calderon = { x: calderon.x, z: calderon.z, heading: Math.atan2(cathedral.x - calderon.x, cathedral.z - calderon.z) };
  for (const id of ['catedral', 'sanfrancisco', 'mercado10', 'todossantos', 'bancocentral', 'terminal', 'universidad', 'turi']) {
    if (CUENCA_LANDMARKS.some((l) => l.id === id)) TELEPORT_LOCATIONS[id] = spot(id);
  }
}
const SPAWN = TELEPORT_LOCATIONS.calderon;

/** Compatibility with the module that used the old avenue / street numbering: Cuenca's spawn */
const streetZ = () => SPAWN.z;

function getLocationLabel(x, z) {
  const near = nearestRoads(x, z, 160);
  for (const lm of CUENCA_LANDMARKS) {
    if (Math.hypot(x - lm.x, z - lm.z) < 70) return near.length ? `${lm.name} · ${near[0].road.name}` : lm.name;
  }
  // Two streets that cross: the nearest, and the nearest running across it
  const first = near[0];
  if (first) {
    const across = near.find((r) => r !== first && r.road.name !== first.road.name && Math.abs(r.dx * first.dz - r.dz * first.dx) / (Math.hypot(r.dx, r.dz) * Math.hypot(first.dx, first.dz) || 1) > 0.5);
    return across ? `${first.road.name} & ${across.road.name}` : first.road.name;
  }
  return 'Cuenca';
}

// Keyboard shortcuts are ignored while typing into a form field
function isTypingInField(e) {
  return e.target && (e.target.tagName === 'INPUT' || e.target.tagName === 'SELECT');
}

// Traffic signal cycle shared by the signal heads and the traffic, in seconds: the main street is green until
// avenueAmber, amber until avenueRed; cross streets are green from avenueRed until streetAmber, amber until the end of
// the cycle. Pedestrians cross with the traffic that runs parallel to them.
const SIGNAL_TIMING = { cycle: 60, avenueAmber: 26, avenueRed: 30, streetAmber: 56, walk: 7 };
function signalPhase(time, isAvenue) {
  const { cycle, avenueAmber, avenueRed, streetAmber } = SIGNAL_TIMING;
  const t = ((time % cycle) + cycle) % cycle;
  if (isAvenue) return t < avenueAmber ? 'green' : t < avenueRed ? 'amber' : 'red';
  return t < avenueRed ? 'red' : t < streetAmber ? 'green' : 'amber';
}

// Do pedestrians walking alongside the main street (or the cross street) traffic have the WALK at a given time?
function walkSignal(time, isAvenue) {
  const { cycle, avenueRed, walk } = SIGNAL_TIMING;
  const t = (((time - (isAvenue ? 0 : avenueRed)) % cycle) + cycle) % cycle;
  return t < walk;
}

export {
  BLOCKS,
  CENTRAL_PARK_BOUNDS,
  CUENCA_LANDMARKS,
  ISLAND_BOUNDS,
  LANDMARK_SITES,
  LONG_ISLAND_POLYGONS,
  NJ_SHORELINE_POLYGON,
  ROADS,
  SIGNAL_TIMING,
  SPAWN,
  TELEPORT_LOCATIONS,
  TERRAIN,
  TERRAIN_BASE,
  blockAt,
  blocksInRect,
  getIslandBoundsAtZ,
  getLocationLabel,
  groundHeightAt,
  planeAt,
  terrainHeightAt,
  isTypingInField,
  nearestRoads,
  roadSpotNear,
  signalPhase,
  streetZ,
  walkSignal
};
